import logging
from datetime import datetime


def initialize_server_logger(log_path, logger):
    timestamp = datetime.now().strftime("%y.%m.%d_%H-%M-%S")
    server_log_handler = logging.FileHandler(str(log_path / f"{logger.name}_{timestamp}.log"))
    server_log_handler.setFormatter(logging.Formatter("%(asctime)s  (%(levelname)s) - %(message)s"))
    logger.addHandler(server_log_handler)
    logger.addHandler(logging.StreamHandler())
    logger.setLevel(logging.DEBUG)
    _initialize_pyro_loggers(log_path, timestamp)
    return logger


def _initialize_pyro_loggers(log_path, timestamp):
    pyro_log_handler = logging.FileHandler(str(log_path / f"pyro_{timestamp}.log"))
    for logger in (logging.getLogger("Pyro4"), logging.getLogger("Pyro4.core")):
        logger.addHandler(pyro_log_handler)
        logger.setLevel(logging.DEBUG)
